import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d as I,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"GDSII 与 OASIS","description":"","frontmatter":{"title":"GDSII 与 OASIS","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/gdsii-oasis.md","filePath":"litho/gdsii-oasis.md","lastUpdated":1789023840000}'),A={name:"litho/gdsii-oasis.md"};function h(p,a,c,E,D,O){const S=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="gdsii-与-oasis" tabindex="-1">GDSII 与 OASIS <a class="header-anchor" href="#gdsii-与-oasis" aria-label="Permalink to &quot;GDSII 与 OASIS&quot;">​</a></h1><div class="epigraph"><p>版图若不能无损、可核对、可压缩地交给掩模厂，后面的 MPC、写入和检验都在猜客户想印什么。</p><footer>—— 对照 SEMI P39 OASIS 与 Calma GDSII 流格式的产业通称</footer></div><p><a href="/litho/high-na-throughput-economics">上一课</a>把高 NA 的产能与片成本钉成经济账。缺口是：晶圆侧再贵的光子，也要先变成一张可写的版。本课起一门新课——掩模制造与数据准备——从交换格式钉起。分层与布尔派生，留给[下一课](/litho/layout-layers-flow）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设计库交出来的是多边形流，不是扫描机认的铬图。历史上的交换语言是 Calma GDSII：层号、数据类型、边界、路径、结构引用。它能表达几乎一切曼哈顿与折线多边形，但重复单元、曲线逼近和小 jog 会把文件胀到 TAPOUT 墙。SEMI P39 的 OASIS（Open Artwork System Interchange Standard）用更紧的重复记录、模态坐标和压缩，把同一套几何收成小一个数量级的流；面向写版的 OASIS.MASK（SEMI P44）再限制成掩模厂吃得下的子集。</p><p>缺口因此是<strong>交接口径</strong>，不是再讲一次 <a href="/litho/opc">OPC</a> 怎么挪边。把 GDSII 当「唯一真实」，会在曲线 ILT 上先撞磁盘与网络；把 OASIS 当「另一种画图软件」，会漏掉：校验和、模态计数与精确网格必须与合同里的数据库单位一致，否则后道 fracturing 在对另一张图。</p><h3 id="数据库单位不是显示精度" tabindex="-1">数据库单位不是显示精度 <a class="header-anchor" href="#数据库单位不是显示精度" aria-label="Permalink to &quot;数据库单位不是显示精度&quot;">​</a></h3><p>GDSII/OASIS 的坐标是整数网格。用户单位（微米）乘以数据库单位才是纳米级边。网格若粗于写模地址栅，OPC 碎边会先量化误差；网格若细到亚纳米却没有对应的写栅，只是把文件和 MRC 检查变慢。合同必须写清 DBU、精度与允许的几何类型（路径是否先展成边界、是否允许曲线记录）。</p><p><span class="marginnote">OASIS 不是「压缩包里的 GDS」。它是另一种记录语法。比对必须在展开后的几何等价上做，不能比文件字节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流的路径：设计 GDS/OASIS → 层映射与派生 → OPC/ILT 输出 → 掩模数据准备。每一跳都要能回答：多边形集合是否与上一跳等价（在约定公差内）。OASIS 的 repetition、ctrans 和 modal variables 是为了让标准单元阵列和 SRAM 不把同一多边形写一万遍；展开给 fracturing 时必须可逆核对。</p><p>曲线层若仍先折成微矩形再进 GDSII，文件与 <a href="/litho/curvilinear-mrc">曲线 MRC</a> 会一起炸。能走原生曲边或密折线的 OASIS 路径，才是后课数据量课的前提。本课只钉：格式选错，后面所有校正都在错误几何上算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GDSII 是顺序记录加结构层次；引用深度一深，流式工具必须建符号表。OASIS 把常用属性变成模态——下一条记录默认继承坐标与层——所以解码器状态机错一位，后面整层错位。这就是为什么掩模厂要官方校验器，而不是「能打开的浏览图」。</p><p>网格量化是第一种系统误差：边被吸到最近网格点，短 jog 消失或加倍。这与晶圆侧 MEF 无关，却会在写版 PEC 之前就已经改了频谱。后课默认：说到「客户数据」，先问是 GDSII 还是 OASIS、DBU 多少、是否 OASIS.MASK 子集。</p>',15)),(e(),s(d,null,{default:i(()=>[n(S,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%20GDS%20%2F%20OASIS%22%5D%20--%3E%20MAP%5B%22%E5%B1%82%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20OPC%5B%22OPC%20%2F%20ILT%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20OPC%20--%3E%20MASK%5B%22OASIS.MASK%20%2F%20%E4%BD%9C%E4%B8%9A%E5%8D%95%22%5D%0A%20%20MASK%20--%3E%20FRAC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%88%86%E5%89%B2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[I(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>格式不提高 NA，不缩短写入时间。它只决定几何能否无损到达 MDP。专利与加密包装（某些专有流）若不能在掩模厂展开核对，检验的 die-to-database 会失去金标准。不要发明「OASIS 比 GDS 一定准一个数量级」的 CD 数字——准的是语法与压缩，不是光刻分辨率。</p><p>后课默认读者已经知道：掩模链的输入是带网格的多边形流；层怎么变成一张版，下一课才拆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GDSII 是历史交换流；OASIS / OASIS.MASK 是为重复与掩模子集收紧的 SEMI 格式。</li><li>合同要写 DBU、几何类型与等价核对，不能只比文件大小。</li><li>曲线层不应先折成微矩形再进 GDSII，否则文件与 MRC 先炸。</li><li>出处：SEMI P39 OASIS；SEMI P44 OASIS.MASK；Calma GDSII 流惯例。</li></ul>',5))])}const u=o(A,[["render",h]]);export{_ as __pageData,u as default};
